\documentclass{article}
\usepackage{pgfplots}
\usepackage{tikz}
\usetikzlibrary{arrows}
\usetikzlibrary{intersections}
\usepgfplotslibrary{fillbetween}

\newcommand{\midarrow}{\tikz \draw[-triangle 90] (0,0) -- +(.1,0);}

\definecolor{verylightgray}{RGB}{242, 242, 242}


\begin{document}

\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

	\pagestyle{empty}



\begin{tikzpicture}

\begin{axis}[
legend pos=outer north east,
tick label style={font=\footnotesize},
label style={font=\small},
legend style={font=\footnotesize},
tick style={draw=none},
axis line style = thick,
axis y line = center,
axis x line = middle,
axis equal,
%grid = both,
xmin = -2.5,
xmax = 2.5,
ymin = -1.5,
ymax = 5.5,
xtick = {0},
ytick = {0},     
xlabel = $x$,
ylabel = {$y$},
xlabel style={below right},
ylabel style={above right},
every axis x label/.style={
	at={(ticklabel* cs:1.02)},
	anchor=west,
},
every axis y label/.style={
	at={(ticklabel* cs:1.02)},
	anchor=south,
}
]


\addplot [
domain=-4:4,
samples=100,
color=deepskyblue,
line width=1pt,
]{3*x^2-6*x+5};


\node[circle,orangepeel,fill,inner sep=1.5pt, label={below, xshift=0pt: \small $\left(1,2\right)$}] (B) at (axis cs: 1,2) {};

\end{axis}

\end{tikzpicture}

\end{document}

